import{_ as r,o as e,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"AI 与手术机器人晨报｜2026-08-03","description":"","frontmatter":{},"headers":[],"relativePath":"2026-08-03-AI与手术机器人晨报.md","filePath":"2026-08-03-AI与手术机器人晨报.md","lastUpdated":1786237923000}'),n={name:"2026-08-03-AI与手术机器人晨报.md"};function i(l,a,s,h,g,d){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-与手术机器人晨报-2026-08-03" tabindex="-1">AI 与手术机器人晨报｜2026-08-03 <a class="header-anchor" href="#ai-与手术机器人晨报-2026-08-03" aria-label="Permalink to &quot;AI 与手术机器人晨报｜2026-08-03&quot;">​</a></h1><blockquote><p><strong>主题：别问模型“你有多确定”——把可靠性改造成可核验的运行时证据</strong></p><p>信息窗口：2026-07-31 至 2026-08-03（北京时间）。arXiv 周末没有新的工作日批次，本期主要筛选 7 月 31 日公开列表中尚未覆盖、且对 AI Native、机器人学习和远程手术系统设计有直接工程价值的论文。近 72 小时未检索到可由监管机构、医院或论文原文交叉核验的新远程手术临床里程碑，也没有新的高价值手术机器人监管决定，因此本期不重复更早的产品新闻。所有论文均为预印本或 workshop 论文，作者结果尚待独立复现。</p></blockquote><hr><h2 id="今日摘要" tabindex="-1">今日摘要 <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;今日摘要&quot;">​</a></h2><ol><li><strong>Agent 安全的最小单元正在从“整段回答”下沉到“即将执行的具体动作”。</strong> HALO 把一条结构化响应拆成带依赖关系的组件，只保留仍有当前证据支持的部分，并在动作真正越过执行边界前重新核验同一个 payload、依赖和授权。它在 UAV/PX4 环境中验证的是运行时协议，不是模型变得更可信。</li><li><strong>模型自报置信度可能不足以分配人工审计预算。</strong> “One Human, N Agents”显示，在其锁定协议下，五个开源权重模型的口头置信度几乎恒定，错误排序能力接近随机；当多个 Agent 因同一道难题共同出错时，“换模型家族”也未必能消除相关性。</li><li><strong>派生指标不能被下游 LLM 当作直接事实。</strong> 一项 PPG—ECG 研究把“测量值的实例级可靠性”作为独立证据输入，虽让四项修复/特异性指标提升 1.82–6.69 个百分点，但仍有 55.17% 的刻意诱导错误未修复。可靠性标签有用，但不是免责开关。</li><li><strong>安全约束只有在部署时可观测，才有机会成为真实保护。</strong> PAC-MAN 中更精细的 Joint-CBF 在准确球状态下有效，却在固定机载相机下退化；更粗但与观测能力匹配的 Link-CBF 在 Unitree G1 的 20 次实物投掷中躲过 19 次。约束精度不能脱离感知可用性讨论。</li><li><strong>机器人学习的数据重点从“多收成功演示”转向“定位脆弱动作与可恢复失败”。</strong> CFNBC 用不应改变正确动作的反事实视觉扰动测量 action drift，以 20–30 个定向样本接近更大随机修复集；RedFlow 则把失败轨迹拆到动作级，为可恢复失败检索相似情境下的成功替代动作，作者报告真实任务成功率由 56.7% 提升到 74.7%。</li></ol><hr><h2 id="ai-前沿" tabindex="-1">AI 前沿 <a class="header-anchor" href="#ai-前沿" aria-label="Permalink to &quot;AI 前沿&quot;">​</a></h2><h3 id="_1-halo-输出生成完毕-不等于动作仍然有权执行" tabindex="-1">1. HALO：输出生成完毕，不等于动作仍然有权执行 <a class="header-anchor" href="#_1-halo-输出生成完毕-不等于动作仍然有权执行" aria-label="Permalink to &quot;1. HALO：输出生成完毕，不等于动作仍然有权执行&quot;">​</a></h3><p><strong>事实。</strong> HALO 针对一种容易被忽略的时序问题：Agent 生成结构化响应需要时间，期间地图、传感器、权限或外部状态可能已经变化。同一响应里的通知、观测、动作和依赖动作的状态说明，不应被整体接受或整体拒绝。HALO 为每个组件声明类型、payload、依赖与 support footprint；运行时保留“当前仍受支持且依赖闭合”的最大集合，并把动作绑定到 canonical payload 的摘要和一次性授权。在真正调用外部 adapter 前，它再次核验当前证据、依赖阶段、payload 身份和授权新鲜度；被阻止的旧动作不能复活，只能以新候选重新准入。<a href="https://arxiv.org/abs/2607.27636" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.27636" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>作者结果。</strong> HALO 通过了 96 项准入预期与 20 项协议测试；结构化响应回放中保留了 248/248 个仍受支持的组件，而整段拒绝策略保留 0/248；十次冷启动 PX4/Gazebo 会话中，它阻止了所有被测试的过期航路，并完成新候选恢复。</p><p><strong>边界。</strong> 这些保证依赖可信规则目录、忠实的状态提供者、受控 adapter、无环依赖图和正确授权账本。论文只保证动作跨过 adapter 时满足条件，不保证后续物理结果；UAV 仿真也不是医疗器械验证。</p><p><strong>推断。</strong> 对 AI Native 自动化，最值得复用的是“最终执行门”而不是 HALO 的全部形式化：文件写入、Git 提交、推送、外部消息等动作在执行前，应重新核验目标路径、工作区状态、payload digest、分支、远端领先状态和授权，不能沿用几分钟前规划阶段的快照。</p><h3 id="_2-一个监督者管理-n-个-agent-自报置信度可能让审计比随机还差" tabindex="-1">2. 一个监督者管理 N 个 Agent：自报置信度可能让审计比随机还差 <a class="header-anchor" href="#_2-一个监督者管理-n-个-agent-自报置信度可能让审计比随机还差" aria-label="Permalink to &quot;2. 一个监督者管理 N 个 Agent：自报置信度可能让审计比随机还差&quot;">​</a></h3><p><strong>事实。</strong> “One Human, N Agents”研究一个监督者每轮只能审计 <code>B ≪ N</code> 个 Agent 输出的场景，并引入错误相关性与置信度错校准。作者给出一个阈值：错校准超过该点后，优先审计“最低置信度”输出反而劣于随机抽查。在其 500 道 GSM8K / HotpotQA 锁定协议中，五个开源权重模型的口头置信度集中在接近 1.0，方差不高于 0.016，区分错误的 AUROC 约为 0.5；共享任务难度造成的跨模型相关性比模型家族差异更重要。<a href="https://arxiv.org/abs/2607.28317" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.28317" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>来源观点与边界。</strong> 作者把“任何可行审计策略相对不审计的收益都低于给定阈值”定义为 vacuous oversight。实验只覆盖六个模型、两类问答任务和单次口头置信度提示；真实轨迹回放的 Agent fleet 只有 15 个，作者也明确称其为初步结果。不能据此断言所有模型置信度都无用，但足以否定“默认相信 Agent 自己的把握度”。</p><p><strong>交叉核验。</strong> HALO 不使用模型的自信程度决定是否执行，而要求外部规则和当前证据；本研究则说明，当审计资源紧张时，模型自报置信度本身可能不是有效排序信号。两者共同指向：<strong>高风险动作的检查优先级，应由影响范围、证据新鲜度、可逆性、异常信号和随机覆盖共同决定，而不是由模型自评分决定。</strong></p><h3 id="_3-派生测量过度信任-把-值-和-这个值此刻是否可靠-分开" tabindex="-1">3. 派生测量过度信任：把“值”和“这个值此刻是否可靠”分开 <a class="header-anchor" href="#_3-派生测量过度信任-把-值-和-这个值此刻是否可靠-分开" aria-label="Permalink to &quot;3. 派生测量过度信任：把“值”和“这个值此刻是否可靠”分开&quot;">​</a></h3><p><strong>事实。</strong> DFOT 论文研究下游 LLM 把派生测量当作直接事实，或在其有效范围外使用的问题。作者以 PPG 推导的心律为案例，用 ECG 只做离线监督和参考构建，部署时仍只输入 PPG；在 50,000 对 PPG—ECG 记录上学习实例级可靠性证据，并在锁定的 187 名患者测试集上评估。加入匹配的可靠性证据后，四项修复与特异性指标提升 1.82–6.69 个百分点，所有配对置信区间下界高于零；但在一类刻意制造的冲突错误中，仍有 55.17% 未被修复。<a href="https://arxiv.org/abs/2607.28421" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.28421" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>边界。</strong> 这是受控错误诱导和 proof-of-concept，不是临床有效性试验。作者的“可靠性生成器”只是示例，PPG/ECG 结论也不能直接迁移到手术视频、网络质量或机器人状态估计。</p><p><strong>推断。</strong> 远程手术链路中的“平均时延 35 ms”“当前无丢包”“跟踪置信度 0.92”“组织风险低”都属于派生量。它们不应以一个裸数进入 AI 或控制决策，而应携带：原始来源、时间窗、估计方法、适用条件、置信区间/质量等级、失效原因和可追溯原始证据。可靠性是与数值并行的数据对象，不是 UI 上的一颗绿灯。</p><hr><h2 id="手术机器人与远程手术" tabindex="-1">手术机器人与远程手术 <a class="header-anchor" href="#手术机器人与远程手术" aria-label="Permalink to &quot;手术机器人与远程手术&quot;">​</a></h2><h3 id="_1-pac-man-更精细的安全约束-可能因不可观测而更差" tabindex="-1">1. PAC-MAN：更精细的安全约束，可能因不可观测而更差 <a class="header-anchor" href="#_1-pac-man-更精细的安全约束-可能因不可观测而更差" aria-label="Permalink to &quot;1. PAC-MAN：更精细的安全约束，可能因不可观测而更差&quot;">​</a></h3><p><strong>事实。</strong> PAC-MAN 把控制障碍函数（CBF）安全引导与强化学习结合，用于 Unitree G1 躲避来球。部署策略只看到头部相机的分割掩膜深度和本体状态；训练时则可用每个身体 link 与球的间距形成安全引导。作者发现，精细的 Joint-CBF 在准确球状态下表现最好，但只作为固定相机策略的训练引导时明显退化；增加跟踪云台或部署时特权状态 filter 才恢复。与有限观测更匹配的 Link-CBF 被零样本部署到真机，20 次手工投球中躲过 19 次，无跌倒。<a href="https://arxiv.org/abs/2607.28623" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.28623" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>来源观点。</strong> 作者的核心判断是，安全 barrier 是否可用取决于感知可观测性，而不只取决于数学约束是否更精细。</p><p><strong>边界。</strong> 19/20 是小样本、受控来球实验；躲球与柔性组织操作在动力学、风险代价和感知条件上差异巨大。95% 远不构成医疗安全证据。</p><p><strong>推断。</strong> 手术机器人 RL 在定义“安全 reward / shield / CBF”前，应先做可观测性审计：约束所需的组织形变、接触力、器械—组织距离、穿刺深度或滑移状态，在真实器械上能否以足够频率和误差界获得？如果只能在仿真读取真值，精细约束可能只是训练特权，不是部署保护。更粗但可测、可验证的限制，往往比精确但不可观测的风险模型更可靠。</p><h3 id="_2-cfnbc-不要按-看起来多样-选数据-要按策略动作漂移选" tabindex="-1">2. CFNBC：不要按“看起来多样”选数据，要按策略动作漂移选 <a class="header-anchor" href="#_2-cfnbc-不要按-看起来多样-选数据-要按策略动作漂移选" aria-label="Permalink to &quot;2. CFNBC：不要按“看起来多样”选数据，要按策略动作漂移选&quot;">​</a></h3><p><strong>事实。</strong> CFNBC 为已训练的视觉模仿策略生成成对观测：原图与不应改变专家动作的光照、颜色、干扰物等视觉 nuisance。若策略在这对观测上的预测动作发生明显漂移，说明该 nuisance 命中了当前策略的脆弱响应模式。方法在离线状态下用 action drift 从候选池选择响应多样的修复样本，不需要在线 rollout 成功标签。作者在 MuJoCo 双臂方块转移和 SimplerEnv 堆叠中报告，20–30 个定向候选显著优于相同预算的随机选择；方块转移中，随机采样约需 100–500 个样本才能接近其效果。<a href="https://arxiv.org/abs/2607.27261" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.27261" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>边界。</strong> 这是两个仿真任务上的 workshop 论文，nuisance 由研究者定义，尚未覆盖组织形变、烟雾、出血、镜头污染、器械遮挡和跨设备成像差异。</p><p><strong>推断。</strong> 对手术视频/动作数据，数据覆盖不能只看图像域多样性。更有价值的问题是：在临床语义不变的扰动下，策略动作是否变化？可先对已有演示离线加入亮度、白平衡、轻度烟雾、镜头污渍、压缩伪影和无关器械移动，按 action drift 排出最脆弱的状态，再决定补采哪些演示。</p><h3 id="_3-redflow-失败轨迹的价值在于定位-哪一步该换成什么" tabindex="-1">3. RedFlow：失败轨迹的价值在于定位“哪一步该换成什么” <a class="header-anchor" href="#_3-redflow-失败轨迹的价值在于定位-哪一步该换成什么" aria-label="Permalink to &quot;3. RedFlow：失败轨迹的价值在于定位“哪一步该换成什么”&quot;">​</a></h3><p><strong>事实。</strong> RedFlow 面向 flow-matching VLA 策略，把部署失败转化为动作级纠正监督。Context-Aware Corrective Matching 先识别引发失败的 action chunk，再从相似上下文的成功轨迹检索替代动作；训练目标同时强化成功动作、抑制不良动作，并把可恢复失败重定向到纠正目标。作者在 LIBERO 和三个真实机器人任务中报告，真实任务成功率由 56.7% 提升到 74.7%，并以约少一个数量级的样本达到其所比较的 PPO、GRPO、DDPO 在线方法水平。<a href="https://arxiv.org/abs/2607.27782" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2607.27782" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>边界。</strong> “失败动作”与“相似上下文的成功替代”由方法自身估计；分布外状态、长时序任务和错误纠正目标仍是作者列出的后续问题。三项真实任务不是手术任务，74.7% 也远低于临床要求。</p><p><strong>交叉核验与推断。</strong> CFNBC 回答“哪些视觉条件暴露了策略脆弱性”，RedFlow 回答“失败中的哪个动作应被何种动作替代”。两者说明机器人数据闭环至少应保留四层：环境扰动、策略响应变化、失败 action chunk、相似状态下的成功替代。只保存整段“成功/失败”标签，会丢失最有训练价值的因果位置。</p><h3 id="_4-远程手术临床进展-本窗口宁缺毋滥" tabindex="-1">4. 远程手术临床进展：本窗口宁缺毋滥 <a class="header-anchor" href="#_4-远程手术临床进展-本窗口宁缺毋滥" aria-label="Permalink to &quot;4. 远程手术临床进展：本窗口宁缺毋滥&quot;">​</a></h3><p>近 72 小时未发现新的、能由医院/监管机构公告或论文原文核验的远程手术临床实施。本期也未把 7 月 22 日 OTTAVA 获 FDA De Novo 授权等更早新闻重新包装为“今日进展”。远程手术的下一条高价值证据仍应至少报告 P50/P95/P99 端到端时延、抖动、丢包与乱序、视频和控制通道分层、故障注入、接管时间、样本量和不良事件，而不仅是距离或平均延迟。</p><hr><h2 id="论文-产品-监管动态" tabindex="-1">论文 / 产品 / 监管动态 <a class="header-anchor" href="#论文-产品-监管动态" aria-label="Permalink to &quot;论文 / 产品 / 监管动态&quot;">​</a></h2><h3 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h3><ul><li><strong>Agent 运行时：</strong> HALO 把依赖闭合、精确动作绑定、最终执行门和新候选重新准入组合成可测试协议。</li><li><strong>人类监督：</strong> “One Human, N Agents”把置信度错校准和错误相关性纳入有限审计预算，指出形式上存在 human-in-the-loop 不等于监督有效。</li><li><strong>医疗 AI：</strong> DFOT 把派生测量的实例级可靠性作为独立证据，提供修复收益与额外核验代价的共同评估方法。</li><li><strong>机器人安全：</strong> PAC-MAN 揭示 CBF 安全结构与感知可观测性之间的耦合。</li><li><strong>机器人数据闭环：</strong> CFNBC 用动作漂移选择小规模修复集；RedFlow 把失败下钻为动作级纠正目标。</li></ul><h3 id="产品与监管" tabindex="-1">产品与监管 <a class="header-anchor" href="#产品与监管" aria-label="Permalink to &quot;产品与监管&quot;">​</a></h3><p>截至本期检索时间，FDA 的近期高风险召回/早期预警页面未出现近 72 小时新增的手术机器人条目；主流手术机器人厂商也没有满足“一手来源、时间窗口内、具有新增技术或监管证据”的公告。本期因此不扩写产品动态。<a href="https://www.fda.gov/medical-devices/medical-device-safety/medical-device-recalls-and-early-alerts" target="_blank" rel="noreferrer">FDA 医疗器械召回与早期预警</a></p><hr><h2 id="对-nathan-当前项目的启示" tabindex="-1">对 Nathan 当前项目的启示 <a class="header-anchor" href="#对-nathan-当前项目的启示" aria-label="Permalink to &quot;对 Nathan 当前项目的启示&quot;">​</a></h2><h3 id="_1-远程手术-为每个高风险动作建立-证据契约" tabindex="-1">1. 远程手术：为每个高风险动作建立“证据契约” <a class="header-anchor" href="#_1-远程手术-为每个高风险动作建立-证据契约" aria-label="Permalink to &quot;1. 远程手术：为每个高风险动作建立“证据契约”&quot;">​</a></h3><p>选一个实际控制动作或配置变更，定义它在发送前必须同时满足的字段：<code>payload_digest / source / monotonic_time / max_age / prerequisite_state / operator_authorization / single_use_token / fallback</code>。规划阶段检查一次，真正写入控制通道前再检查一次；任何字段变化都生成新候选，禁止复用旧授权。</p><p><strong>完成标准：</strong> 用“网络状态在规划后变化、授权过期、payload 被替换、依赖状态失败、无关日志变化”五类测试验证：前四类必须阻止动作，无关变化不能让整个流程报废；所有决定可追溯到当时证据。</p><h3 id="_2-机器人强化学习-先做约束可观测性表-再设计安全奖励" tabindex="-1">2. 机器人强化学习：先做约束可观测性表，再设计安全奖励 <a class="header-anchor" href="#_2-机器人强化学习-先做约束可观测性表-再设计安全奖励" aria-label="Permalink to &quot;2. 机器人强化学习：先做约束可观测性表，再设计安全奖励&quot;">​</a></h3><p>为进针、夹持或稳定接触任务列出每项安全约束及其运行时传感来源、频率、误差上界、最坏延迟、缺失检测和降级策略。将仿真真值标成 privileged state，逐项验证部署是否真实可得。</p><p><strong>最小实验：</strong> 比较“精细但依赖特权状态的约束”“较粗但真实可观测的约束”“无安全引导”三组；统一报告成功率、峰值力、超限时长、假安全率、推理 P99 和传感失效下结果。不要只比较 nominal success。</p><h3 id="_3-手术机器人数据闭环-把失败拆到动作级" tabindex="-1">3. 手术机器人数据闭环：把失败拆到动作级 <a class="header-anchor" href="#_3-手术机器人数据闭环-把失败拆到动作级" aria-label="Permalink to &quot;3. 手术机器人数据闭环：把失败拆到动作级&quot;">​</a></h3><p>在现有日志 schema 中增加：<code>failure_onset / action_chunk / recoverability / consequence_severity / nearest_success_context / corrective_action / evidence_provenance</code>。先人工标注 20 个失败片段，验证不同工程师是否能对“失败从哪一步开始”和“是否可恢复”达成一致。</p><p><strong>完成标准：</strong> 至少 80% 的样本能定位到不超过一个策略 horizon 的 action chunk；纠正目标可追溯到真实成功轨迹；不可恢复失败不得被硬匹配成看似合理的动作。</p><h3 id="_4-视觉鲁棒性-用-action-drift-决定补采优先级" tabindex="-1">4. 视觉鲁棒性：用 action drift 决定补采优先级 <a class="header-anchor" href="#_4-视觉鲁棒性-用-action-drift-决定补采优先级" aria-label="Permalink to &quot;4. 视觉鲁棒性：用 action drift 决定补采优先级&quot;">​</a></h3><p>对同一段手术/仿真演示生成任务语义不变的成对扰动，先离线测动作输出变化，再按“高 drift + 响应多样性”选择补采或微调样本。这样把有限数据预算投向当前策略真正脆弱的区域，而不是追求抽象的画面多样性。</p><h3 id="_5-ai-native-人工审计采用风险分层-随机覆盖" tabindex="-1">5. AI Native：人工审计采用风险分层 + 随机覆盖 <a class="header-anchor" href="#_5-ai-native-人工审计采用风险分层-随机覆盖" aria-label="Permalink to &quot;5. AI Native：人工审计采用风险分层 + 随机覆盖&quot;">​</a></h3><p>不要让 Agent 的“高/低置信度”直接决定是否人工复核。审计队列至少混合：不可逆或外发动作全检；证据过期/依赖变化优先；同一任务簇出现一次错误后扩大抽查；剩余低风险输出保留随机样本，防止长期盲区。</p><p><strong>完成标准：</strong> 连续记录四周的审计命中率、漏检后果、任务簇相关错误和人工时间；若按置信度排序不优于随机基线，就移除这个无效信号。</p><hr><h2 id="值得继续跟踪的问题" tabindex="-1">值得继续跟踪的问题 <a class="header-anchor" href="#值得继续跟踪的问题" aria-label="Permalink to &quot;值得继续跟踪的问题&quot;">​</a></h2><ol><li>HALO 的 trusted state provider 本身如何验证？远程手术中，网络质量、机器人状态与操作者授权谁是最终事实源？</li><li>最终执行门应放在云端编排层、边缘网关还是机器人控制器？跨层检查如何避免时序竞态？</li><li>Agent fleet 的错误相关性应按模型家族、任务类型、共享上下文还是工具依赖聚类？哪一种最能预测共同失效？</li><li>派生测量的可靠性证据会不会被 LLM 再次过度信任？何时必须触发原始模态复核而不是继续推理？</li><li>手术机器人安全约束中，哪些状态可直接观测，哪些只能估计，哪些目前根本不可辨识？</li><li>action drift 对视觉 nuisance 敏感，但如何避免把真正需要动作改变的组织状态误判为“应保持不变”的扰动？</li><li>RedFlow 的成功替代动作在柔性组织中是否仍安全？相似视觉上下文是否掩盖了不同的组织力学状态？</li><li>如何把失败动作纠正、运行时失效检测和确定性安全控制串成一个闭环，而不让学习策略获得越权恢复能力？</li></ol><hr><h2 id="来源链接" tabindex="-1">来源链接 <a class="header-anchor" href="#来源链接" aria-label="Permalink to &quot;来源链接&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2607.27636" target="_blank" rel="noreferrer">arXiv：HALO——面向状态漂移的 Agent 动作准入与最终执行门（2026-07-30 提交，7 月 31 日公开列表）</a></li><li><a href="https://arxiv.org/abs/2607.28317" target="_blank" rel="noreferrer">arXiv：One Human, N Agents——错校准与相关错误下的审计预算（2026-07-30 提交）</a></li><li><a href="https://arxiv.org/abs/2607.28421" target="_blank" rel="noreferrer">arXiv：DFOT——LLM 对派生生理测量的过度信任（2026-07-30 提交）</a></li><li><a href="https://arxiv.org/abs/2607.28623" target="_blank" rel="noreferrer">arXiv：PAC-MAN——感知可观测性与 CBF-RL 安全结构（2026-07-30 提交）</a></li><li><a href="https://arxiv.org/abs/2607.27261" target="_blank" rel="noreferrer">arXiv：CFNBC——用反事实动作漂移选择鲁棒性修复数据（2026-07-29 提交）</a></li><li><a href="https://arxiv.org/abs/2607.27782" target="_blank" rel="noreferrer">arXiv：RedFlow——把失败轨迹转成动作级纠正监督（2026-07-30 提交）</a></li><li><a href="https://arxiv.org/list/cs.AI/recent" target="_blank" rel="noreferrer">arXiv：cs.AI 最近提交列表（核验 7 月 31 日公开批次）</a></li><li><a href="https://arxiv.org/list/cs.RO/recent" target="_blank" rel="noreferrer">arXiv：cs.RO 最近提交列表（核验 7 月 31 日公开批次）</a></li><li><a href="https://www.fda.gov/medical-devices/medical-device-safety/medical-device-recalls-and-early-alerts" target="_blank" rel="noreferrer">FDA：医疗器械召回与早期预警（核验近期监管动态）</a></li></ul><hr><p><em>事实以链接所示原始来源为准；“来源观点”是作者的解释；“推断”是结合 Nathan 当前远程手术、机器人强化学习与 AI Native 项目给出的工程判断。预印本、workshop 论文、仿真结果和小样本实物实验，在同行评议、独立复现、真实组织实验和临床验证前，均不应外推为医疗安全或有效性结论。</em></p>',67)])])}const f=r(n,[["render",i]]);export{p as __pageData,f as default};
